WITH params AS (SELECT coalesce(%s::text, '') AS machine_code, coalesce(%s::text, '') AS branch_code, coalesce(%s::text, '') AS status, %s::integer AS authenticated_user_id, %s::integer AS row_limit), scope AS (SELECT p.*, u.user_id AS authorized_user_id, coalesce(u.ds_branchs, '') AS ds_branchs, coalesce(u.is_super, 0) = 1 OR coalesce(u.ds_branchs, '') = '' AS unrestricted FROM params p LEFT JOIN public.userinfo u ON u.user_id = p.authenticated_user_id)
SELECT m.machine_code, m.machine_name, m.machine_name2, m.technical_description, m.capacity, m.efficiency, m.number_of_workers, m.year_of_manufacture, m.country_of_manufacture, m.branch_code, m.serial, m.length, m.width, m.height, m.weight, m.date_of_entry, m.ip_address, m.port, m.status, m.date0, m.time0, m.user_id0, m.date2, m.time2, m.user_id2, m.user_appr, m.date_appr, m.time_appr, m.may_duc_yn, count(*) OVER () AS total
FROM public.mflist_machine m CROSS JOIN scope s
WHERE s.authorized_user_id IS NOT NULL AND (s.machine_code = '' OR m.machine_code = ANY(string_to_array(s.machine_code, ','))) AND (s.branch_code = '' OR m.branch_code = ANY(string_to_array(s.branch_code, ','))) AND (s.status = '' OR m.status::text = ANY(string_to_array(s.status, ','))) AND (s.unrestricted OR m.branch_code = ANY(string_to_array(s.ds_branchs, ',')))
ORDER BY m.machine_code LIMIT (SELECT row_limit FROM params);
